CREATE TABLE IF NOT EXISTS chatbot_faqs (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, category TEXT NOT NULL DEFAULT 'general', question TEXT NOT NULL, keywords TEXT NOT NULL DEFAULT '', answer_template TEXT NOT NULL DEFAULT '', answer_type TEXT NOT NULL DEFAULT 'static', is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)), sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX IF NOT EXISTS idx_chatbot_faqs_active_order ON chatbot_faqs(is_active, sort_order, id);
